// Подготовка задачи автозагрузки.
// Здесь задаются все настройки, которые не являются секретами.
// Секреты (service-ключ Supabase) хранятся в учетных данных n8n, а не тут.

const CONFIG = {
  supabaseUrl: 'https://ВАШ-ПРОЕКТ.supabase.co',   // без слэша на конце
  bucket: 'dashboard-csv',                          // SUPABASE_STORAGE_BUCKET
  projectId: '',                                    // можно оставить пустым и резолвить по sourceKey
  sourceKey: 'brand-analytics-weekly',              // ключ источника в платформе
  sourceSystem: 'brand_analytics',                  // auto | brand_analytics | mediologia | mediologia_excel | generic
  // Письмо берется в работу, только если отправитель содержит одну из строк.
  allowedSenders: ['br-analytics.ru', 'brandanalytics.ru'],
  // И тема письма содержит эту строку (пустая строка = не проверять тему).
  subjectContains: '',
  allowedExtensions: ['.xlsx', '.xls', '.xlsm', '.csv'],
};

const out = [];

for (const item of $input.all()) {
  const json = item.json || {};
  const binary = item.binary || {};

  const from = String(json.from || json.fromEmail || '').toLowerCase();
  const subject = String(json.subject || '');

  const senderOk =
    CONFIG.allowedSenders.length === 0 ||
    CONFIG.allowedSenders.some((s) => from.includes(String(s).toLowerCase()));
  const subjectOk =
    !CONFIG.subjectContains || subject.toLowerCase().includes(CONFIG.subjectContains.toLowerCase());

  if (!senderOk || !subjectOk) continue;

  for (const [property, meta] of Object.entries(binary)) {
    const fileName = String(meta.fileName || 'upload.xlsx');
    const lower = fileName.toLowerCase();
    const extOk = CONFIG.allowedExtensions.some((ext) => lower.endsWith(ext));
    if (!extOk) continue;

    // Латинизируем имя для пути в Storage: кириллица в ключах объектов ломает ссылки.
    const safeName = fileName
      .normalize('NFKD')
      .replace(/[^\w.\-]+/g, '_')
      .replace(/_+/g, '_')
      .slice(-120) || 'upload.xlsx';

    const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
    const folder = CONFIG.projectId || CONFIG.sourceKey || 'inbox';

    out.push({
      json: {
        supabaseUrl: CONFIG.supabaseUrl.replace(/\/+$/, ''),
        bucket: CONFIG.bucket,
        projectId: CONFIG.projectId || null,
        sourceKey: CONFIG.sourceKey,
        sourceSystem: CONFIG.sourceSystem,
        originalFilename: fileName,
        storagePath: `inbox/${folder}/${stamp}_${safeName}`,
        binaryProperty: property,
        fileSize: Number(meta.fileSize || 0),
        emailSubject: subject,
        emailFrom: from,
        emailDate: json.date || '',
        executionId: $execution.id,
      },
      binary: { attachment: meta },
    });
  }
}

if (out.length === 0) {
  // Ни одного подходящего вложения — дальше по цепочке идти незачем.
  return [];
}

return out;

