// Форматирование уведомления об итогах обработки.
// Воркер шлет сюда JSON: сколько периодов загружено и какие задачи упали.
const data = $json.body || $json;
const periods = data.periods || [];
const errors = data.errors || [];

const lines = [];
lines.push(periods.length ? `Загружено периодов: ${periods.length}` : 'Новых периодов нет');
for (const p of periods) {
  lines.push(`• ${p.period_name} — сообщений ${p.messages}, инфоповодов ${p.events}`);
}
if (errors.length) {
  lines.push('');
  lines.push(`Ошибки: ${errors.length}`);
  for (const e of errors) {
    lines.push(`• ${e.task_id}: ${String(e.error).slice(0, 200)}`);
  }
}

return [{ json: { text: lines.join('\n'), hasErrors: errors.length > 0, raw: data } }];
